+fn strip(f: &mut Vec<Triangle>, width: f64) {
+    let q = Point3::new;
+    let x = 9.9;
+    f.push(Triangle::new(q(x, 0.0, 0.0), q(x, width, 0.0), q(x, width, 20.0)));
+    f.push(Triangle::new(q(x, 0.0, 0.0), q(x, width, 20.0), q(x, 0.0, 20.0)));
+}
